package com.clearchoice;
import android.content.*;import android.view.accessibility.*;import java.util.*;

public final class Engine {
 public static final String STORE="com.demoshop"; public static final String[] STATES={"OFF","PERMISSION_CHECK","READY","APP_DETECTED","ANALYZING","RENDERING","ACTIVE","PAUSED","ERROR"};
 public static final class Item { public String id,label,value,viewId,clazz;public int[] bounds;public boolean clickable,scrollable,selected,checked;public Item(String i,String l,String v,String vi,String c,int[] b,boolean cl,boolean sc,boolean se,boolean ch){id=i;label=l;value=v;viewId=vi;clazz=c;bounds=b;clickable=cl;scrollable=sc;selected=se;checked=ch;} }
 public static final class Rule {public String id,title,detail;public int severity;Rule(String i,String t,String d,int s){id=i;title=t;detail=d;severity=s;}}
 private static final String PREF="cc",LOG="eventlog";
 public static void state(Context c,String s){prefs(c).edit().putString("state",s).apply();}public static String state(Context c){return prefs(c).getString("state","OFF");}
 public static void log(Context c,String s){String old=prefs(c).getString(LOG,"");String entry=System.currentTimeMillis()+"|"+s;String[] a=(entry+"\n"+old).split("\n");StringBuilder b=new StringBuilder();for(int i=0;i<Math.min(30,a.length);i++){if(i>0)b.append('\n');b.append(a[i]);}prefs(c).edit().putString(LOG,b.toString()).apply();}public static String log(Context c){return prefs(c).getString(LOG,"No local activity yet.");}
 public static boolean enabled(Context c){return prefs(c).getBoolean("app_enabled",false);}public static boolean paused(Context c){return prefs(c).getBoolean("paused",false);}
 public static boolean protectedScreen(List<Item> items,String screen){String screenName=screen==null?"":screen.toLowerCase(Locale.ROOT);if(has(screenName,"checkout","payment","login","sign in","authentication"))return true;for(Item i:items){String s=(i.label+" "+i.value).toLowerCase(Locale.ROOT);if(has(s,"password","passcode","card number","cvv","security code","one time password","otp","billing address","demo checkout","guest checkout","continue as guest"))return true;}return false;}
 public static List<Rule> analyze(List<Item> items){StringBuilder b=new StringBuilder();for(Item i:items)b.append(' ').append(i.label).append(' ').append(i.value);String s=b.toString().toLowerCase(Locale.ROOT);ArrayList<Rule> r=new ArrayList<>();boolean extraChecked=false;for(Item i:items)if(i.checked&&has((i.label+" "+i.value).toLowerCase(Locale.ROOT),"subscribe","protection plan","warranty","donation","gift wrap"))extraChecked=true;if(extraChecked)r.add(new Rule("extra","Optional extra is selected","A checked add-on appears in the current screen snapshot.",2));else if(has(s,"subscribe","protection plan","warranty","add donation","gift wrap"))r.add(new Rule("extra","Optional extra mentioned","Check whether an add-on is selected; mention alone does not establish selection.",1));if(has(s,"delivery fee","service fee","handling fee","fees at checkout","tax added"))r.add(new Rule("fees","Additional fees mentioned","Review the fee amount and when it is added.",1));if(has(s,"only 1 left","only one left","hurry","limited time","ends in","people are viewing"))r.add(new Rule("urgency","Urgency language detected","The claim has not been independently verified.",2));if(has(s,"no thanks, i don't want","i don't want to save","i don't want to protect","i prefer to miss out"))r.add(new Rule("shame","Decline wording may add pressure","The decline label uses self-critical wording.",2));if(has(s,"accept all")&&has(s,"manage choices"))r.add(new Rule("choices","Choice prominence may differ","Review the available paths before deciding.",1));int continueCount=0;for(Item i:items)if(i.label.equalsIgnoreCase("continue"))continueCount++;if(continueCount>2)r.add(new Rule("nav","Repeated continue choices","Check that each path and its destination are clear.",1));if(items.size()>28)r.add(new Rule("clutter","Many visible controls","Scroll the original page to review more.",0));for(Item i:items)if(i.label.isEmpty()&&i.clickable){r.add(new Rule("access","Control without a text label","This control may be difficult for screen reader users.",2));break;}if(has(s,"auto renew","recurring","cancel anytime","conditions apply","as applicable","subject to change","based on availability"))r.add(new Rule("terms","Terms may need clarification","Review the complete terms before proceeding.",1));if(r.isEmpty())r.add(new Rule("clear","No listed pattern detected","This screen may still contain choices that need review.",0));return r;}
 static boolean has(String s,String... terms){for(String t:terms)if(s.contains(t))return true;return false;}static SharedPreferences prefs(Context c){return c.getSharedPreferences(PREF,0);}private Engine(){}
}
